const struct json_attr_t *cursor;
    int substatus, maxlen = 0;
    unsigned int u;
    const struct json_enum_t *mp;
    char *lptr;

    if (NULL != end) {
        *end = NULL;    // give it a well-defined value on parse failure
    }

    // stuff fields with defaults in case they're omitted in the JSON input
    for (cursor = attrs; cursor->attribute != NULL; cursor++)
        if (!cursor->nodefault) {
            lptr = json_target_address(cursor, parent, offset);
            if (NULL != lptr)
                switch (cursor->type) {
                case t_byte:
                    lptr[0] = cursor->dflt.byte;
                    break;
                case t_ubyte:
                    lptr[0] = cursor->dflt.ubyte;
                    break;
                case t_integer:
                    memcpy(lptr, &cursor->dflt.integer, sizeof(int));
                    break;
                case t_uinteger:
                    memcpy(lptr, &cursor->dflt.uinteger, sizeof(unsigned int));
                    break;
                case t_longint:
                    memcpy(lptr, &cursor->dflt.longint, sizeof(long));
                    break;
                case t_ulongint:
                    memcpy(lptr, &cursor->dflt.ulongint,
                           sizeof(unsigned long));
                    break;
                case t_short:
                    memcpy(lptr, &cursor->dflt.shortint, sizeof(short));
                    break;
                case t_ushort:
                    memcpy(lptr, &cursor->dflt.ushortint,
                           sizeof(unsigned short));
                    break;
                case t_time:
                    memcpy(lptr, &cursor->dflt.ts, sizeof(timespec_t));
                    break;
                case t_timespec:
                    memcpy(lptr, &cursor->dflt.ts, sizeof(timespec_t));
                    break;
                case t_real:
                    memcpy(lptr, &cursor->dflt.real, sizeof(double));
                    break;
                case t_string:
                    if (parent != NULL
                        && parent->element_type != t_structobject
                        && offset > 0)
                        return JSON_ERR_NOPARSTR;
                    lptr[0] = '\0';
                    break;
                case t_boolean:
                    memcpy(lptr, &cursor->dflt.boolean, sizeof(bool));
                    break;
                case t_character:
                    lptr[0] = cursor->dflt.character;
                    break;
                case t_object:  // silences a compiler warning
                    FALLTHROUGH
                case t_structobject:
                    FALLTHROUGH
                case t_array:
                    FALLTHROUGH
                case t_check:
                    FALLTHROUGH
                case t_ignore:
                    break;
                }
        }

    json_debug_trace((1, "JSON parse of '%s' begins.\n", cp));

    // parse input JSON
    for (; *cp != '\0'; cp++) {
        json_debug_trace((2, "State %-14s, looking at '%c' (%p)\n",
                          statenames[state], *cp, cp));
        switch (state) {
        case init:
            if (isspace((unsigned char) *cp)) {
                continue;
            }
            if (*cp == '{') {
                state = await_attr;
            } else {
                json_debug_trace((1,
                                  "Non-WS when expecting object start.\n"));
                if (NULL != end) {
                    *end = cp;
                }
                return JSON_ERR_OBSTART;
            }
            break;
        case await_attr:
            if (isspace((unsigned char) *cp)) {
                continue;
            }
            if (*cp == '"') {
                state = in_attr;
                pattr = attrbuf;
                if (NULL != end) {
                    *end = cp;
                }
            } else if (*cp == '}') {
                break;
            } else {
                json_debug_trace((1, "Non-WS when expecting attribute.\n"));
                if (NULL != end) {
                    *end = cp;
                }
                return JSON_ERR_ATTRSTART;
            }
            break;
        case in_attr:
            if (NULL == pattr) {
                // don't update end here, leave at attribute start
                return JSON_ERR_NULLPTR;
            }
            if (*cp == '"') {
                *pattr++ = '\0';
                json_debug_trace((1, "Collected attribute name %s\n",
                                  attrbuf));
                for (cursor = attrs; cursor->attribute != NULL; cursor++) {
                    json_debug_trace((2, "Checking against %s\n",
                                      cursor->attribute));
                    if (strcmp(cursor->attribute, attrbuf) == 0) {
                        break;
                    }
                    if (cursor->type == t_ignore &&
                        strncmp(cursor->attribute, "", 1) == 0) {
                        break;
                    }
                }
                if (NULL == cursor->attribute) {
                    json_debug_trace((1,
                                      "Unknown attribute name '%s'"
                                      " (attributes begin with '%s').\n",
                                      attrbuf, attrs->attribute));
                    // don't update end here, leave at attribute start
                    return JSON_ERR_BADATTR;
                }
                state = await_value;
                if (cursor->type == t_string) {
                    maxlen = (int)cursor->len - 1;
                } else if (cursor->type == t_check) {
                    maxlen = (int)strnlen(cursor->dflt.check, JSON_VAL_MAX);
                } else if (cursor->type == t_time ||
                           cursor->type == t_ignore) {
                    maxlen = JSON_VAL_MAX;
                } else if (NULL != cursor->map) {
                    maxlen = (int)sizeof(valbuf) - 1;
                }
                pval = valbuf;
            } else if (pattr >= attrbuf + JSON_ATTR_MAX - 1) {
                json_debug_trace((1, "Attribute name too long.\n"));
                // don't update end here, leave at attribute start
                return JSON_ERR_ATTRLEN;
            } else {
                *pattr++ = *cp;
            }
            break;
        case await_value:
            if (isspace((unsigned char) *cp) ||
                *cp == ':') {
                continue;
            }
            if (*cp == '[') {
                if (cursor->type != t_array) {
                    json_debug_trace((1,
                                      "Saw [ when not expecting array.\n"));
                    if (NULL != end) {
                        *end = cp;
                    }
                    return JSON_ERR_NOARRAY;
                }
                substatus = json_read_array(cp, &cursor->addr.array, &cp);
                if (substatus != 0) {
                    return substatus;
                }
                state = post_element;
            } else if (cursor->type == t_array) {
                json_debug_trace((1,
                                  "Array element was specified, but no [.\n"));
                if (NULL != end) {
                    *end = cp;
                }
                return JSON_ERR_NOBRAK;
            } else if (*cp == '"') {
                value_quoted = true;
                state = in_val_string;
                pval = valbuf;
            } else {
                value_quoted = false;
                state = in_val_token;
                pval = valbuf;
                *pval++ = *cp;
            }
            break;
        case in_val_string:
            if (NULL == pval) {
                // don't update end here, leave at value start
                return JSON_ERR_NULLPTR;
            }
            if (*cp == '\\') {
                state = in_escape;
            } else if (*cp == '"') {
                *pval++ = '\0';
                json_debug_trace((1, "Collected string value %s\n", valbuf));
                state = post_val;
            } else if (pval > valbuf + JSON_VAL_MAX - 1 ||
                       pval > valbuf + maxlen - 1) {
                json_debug_trace((1, "String value too long.\n"));
                // don't update end here, leave at value start
                return JSON_ERR_STRLONG;
            } else {
                *pval++ = *cp;
            }
            break;
        case in_escape:
            if (NULL == pval) {
                /* don't update end here, leave at value start */
                return JSON_ERR_NULLPTR;
            }
            if (pval > valbuf + JSON_VAL_MAX - 1 ||
                pval > valbuf + maxlen) {
                json_debug_trace((1, "String value too long.\n"));
                // don't update end here, leave at value start
                return JSON_ERR_STRLONG;
            }
            switch (*cp) {
            case 'b':
                *pval++ = '\b';
                break;
            case 'f':
                *pval++ = '\f';
                break;
            case 'n':
                *pval++ = '\n';
                break;
            case 'r':
                *pval++ = '\r';
                break;
            case 't':
                *pval++ = '\t';
                break;
